 "content": "from collections import deque


def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append(obj)
    return result


def _guide(grid):
    """Find the large connected L-shaped color guide and its elbow/arms."""
    h, w = len(grid), len(grid[0])
    best = None
    for color in set(v for row in grid for v in row):
        for obj in components(grid, color):
            if len(obj) < 5:
                continue
            rs = [r for r, _ in obj]
            cs = [c for _, c in obj]
            rmin, rmax, cmin, cmax = min(rs), max(rs), min(cs), max(cs)
            # Candidate elbow is a pixel with the strongest perpendicular arms.
            for r, c in obj:
                up = sum((rr, c) in obj for rr in range(r - 1, rmin - 1, -1))
                down = sum((rr, c) in obj for rr in range(r + 1, rmax + 1))
                left = sum((c0, cc) in obj for cc in range(c - 1, cmin - 1, -1))
                right = sum((c0, cc) in obj for cc in range(c + 1, cmax + 1))
                # Arms point away from the elbow. Favor long, perpendicular arms.
                for vr in (up, down):
                    for hc in (left, right):
                        score = min(vr, hc) * 100 + vr + hc
                        if score >= 500 and (best is None or score > best[0]):
                            best = (score, color, obj, (r, c), vr, hc,
                                    'up' if vr == up else 'down',
                                    'left' if hc == left else 'right')
    return best


def transform(grid):
    out = [row[:] for row in grid]
    guide = _guide(grid)
    if guide is None:
        return out
    _, guide_color, guide_obj, (er, ec), _, _, vdir, hdir = guide
    # The guide's open quadrant is opposite the directions of its two arms.
    open_r = 1 if vdir == 'up' else -1
    open_c = 1 if hdir == 'left' else -1
    h, w = len(grid), len(grid[0])

    candidates = []
    for color in set(v for row in grid for v in row):
        if color == guide_color:
            continue
        for obj in components(grid, color):
            if len(obj) < 2:
                continue
            # Components on the open side of the elbow are candidates.
            dr = sum(r - er for r, _ in obj) / len(obj)
            dc = sum(c - ec for _, c in obj) / len(obj)
            if dr * open_r <= 0 or dc * open_c <= 0:
                continue
            # Distance to the nearest point is useful when the guide abuts its target.
            distance = min(abs(r - er) + abs(c - ec) for r, c in obj)
            candidates.append((distance, -len(obj), color, obj))
    if not candidates:
        return out
    _, _, target_color, target = min(candidates, key=lambda x: (x[0], x[1]))
    for r, c in target:
        out[r][c] = guide_color
    return out


if __name__ == '__main__':
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
