 "content": "from collections import deque, Counter


def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = set()
            while q:
                y, x = q.popleft()
                obj.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            result.append(obj)
    return result


def _guide(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best = None
    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
        for obj in components(grid, color):
            if len(obj) < 4:
                continue
            for r,c in obj:
                up = sum((rr,c) in obj for rr in range(r-1,-1,-1))
                down = sum((rr,c) in obj for rr in range(r+1,len(grid)))
                left = sum((r,cc) in obj for cc in range(c-1,-1,-1))
                right = sum((r,cc) in obj for cc in range(c+1,len(grid[0])))
                for vl,vd in ((up,'up'),(down,'down')):
                    for hl,hd in ((left,'left'),(right,'right')):
                        if vl >= 2 and hl >= 2:
                            score = 100*min(vl,hl)+vl+hl
                            if best is None or score>best[0]:
                                best=(score,color,(r,c),vd,hd,obj,bg)
    return best


def transform(grid):
    out=[row[:] for row in grid]
    g=_guide(grid)
    if g is None:
        return out
    _, guide_color,(er,ec),vdir,hdir,guide_obj,bg=g
    # Select the nearest small L-like motif in the guide's open diagonal.
    open_dr = 1 if vdir=='up' else -1
    open_dc = 1 if hdir=='left' else -1
    candidates=[]
    for color in set(v for row in grid for v in row):
        if color in (bg,guide_color):
            continue
        for obj in components(grid,color):
            if len(obj)<3:
                continue
            cr=sum(r for r,c in obj)/len(obj); cc=sum(c for r,c in obj)/len(obj)
            if (cr-er)*open_dr<=0 or (cc-ec)*open_dc<=0:
                continue
            # Prefer compact, non-rectangular components; this identifies a small motif.
            rs=[r for r,c in obj]; cs=[c for r,c in obj]
            area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
            holes=area-len(obj)
            dist=min(abs(r-er)+abs(c-ec) for r,c in obj)
            candidates.append((dist, abs(holes-1),len(obj),color,obj))
    if candidates:
        _,_,_,_,target=min(candidates,key=lambda x:(x[0],x[1],x[2]))
        for r,c in target:
            out[r][c]=guide_color
    return out

if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
