def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    all_objs = [(color, obj) for color in set(v for row in grid for v in row) if color != bg
                for obj in components(grid, color)]
    # Find the long connected L-shaped guide, including its elbow and arm directions.
    guides = []
    for color, obj in all_objs:
        if len(obj) < 8:
